public void sendVertexPartition() throws IOException {
    // Data to send
    int partitionId = 13;
    Collection<Vertex<IntWritable, IntWritable, IntWritable, IntWritable>> vertices = new ArrayList<Vertex<IntWritable, IntWritable, IntWritable, IntWritable>>();
    for (int i = 0; i < 10; ++i) {
        TestVertex vertex = new TestVertex();
        vertex.initialize(new IntWritable(i), new IntWritable(i), null, null);
        vertices.add(vertex);
    }
    // Send the request
    SendVertexRequest<IntWritable, IntWritable, IntWritable, IntWritable> request = new SendVertexRequest<IntWritable, IntWritable, IntWritable, IntWritable>(partitionId, vertices);
    client.sendWritableRequest(-1, server.getMyAddress(), request);
