    for (Vertex<IntWritable, IntWritable, IntWritable, IntWritable> vertex : partitionStore.getPartition(partitionId).getVertices()) {
        total += vertex.getId().get();
    }
    assertEquals(total, 45);
}

@Test
public void sendPartitionMessagesRequest() throws IOException {
    // Data to send
    int partitionId = 17;
    Map<IntWritable, Collection<IntWritable>> vertexIdMessages = Maps.newHashMap();
    for (int i = 1; i < 7; ++i) {
        IntWritable vertexId = new IntWritable(i);
        Collection<IntWritable> messages = Lists.newArrayList();
        for (int j = 0; j < i; ++j) {
            messages.add(new IntWritable(j));
        }
        vertexIdMessages.put(vertexId, messages);
    }
    // Send the request
    SendPartitionMessagesRequest<IntWritable, IntWritable, IntWritable, IntWritable> request = new SendPartitionMessagesRequest<IntWritable, IntWritable, IntWritable, IntWritable>(partitionId, vertexIdMessages);
    client.sendWritableRequest(-1, server.getMyAddress(), request);
    client.waitAllRequests();
    // Stop the service
    client.stop();
    server.stop();
    // Check the output
    Iterable<IntWritable> vertices = serverData.getIncomingMessageStore().getDestinationVertices();
    int keySum = 0;
    int messageSum = 0;
    for (IntWritable vertexId : vertices) {
        keySum += vertexId.get();
        Collection<IntWritable> messages = serverData.getIncomingMessageStore().getVertexMessages(vertexId);
        synchronized (messages) {
            for (IntWritable message : messages) {
                messageSum += message.get();
            }
        }
    }
    assertEquals(21, keySum);
    assertEquals(35, messageSum);
}

@Test
public void sendPartitionMutationsRequest() throws IOException {
    // Data to send
    int partitionId = 19;
    Map<IntWritable, VertexMutations<IntWritable, IntWritable, IntWritable, IntWritable>> vertexIdMutations = Maps.newHashMap();
    for (int i = 0; i < 11; ++i) {
        VertexMutations<IntWritable, IntWritable, IntWritable, IntWritable> mutations = new VertexMutations<IntWritable, IntWritable, IntWritable, IntWritable>();
        for (int j = 0; j < 3; ++j) {
            TestVertex vertex = new TestVertex();
            vertex.initialize(new IntWritable(i), new IntWritable(j), null, null);
            mutations.addVertex(vertex);
        }
        for (int j = 0; j < 2; ++j) {
            mutations.removeVertex();
        }
        for (int j = 0; j < 5; ++j) {
            Edge<IntWritable, IntWritable> edge = new Edge<IntWritable, IntWritable>(new IntWritable(i), new IntWritable(2 * j));
            mutations.addEdge(edge);
        }
        for (int j = 0; j < 7; ++j) {
            mutations.removeEdge(new IntWritable(j));
        }
        vertexIdMutations.put(new IntWritable(i), mutations);
    }
    // Send the request
    SendPartitionMutationsRequest<IntWritable, IntWritable, IntWritable, IntWritable> request = new SendPartitionMutationsRequest<IntWritable, IntWritable, IntWritable, IntWritable>(partitionId, vertexIdMutations);
    client.sendWritableRequest(-1, server.getMyAddress(), request);
    client.waitAllRequests();
    // Stop the service
    client.stop();
    server.stop();
    // Check the output
    ConcurrentHashMap<IntWritable, VertexMutations<IntWritable, IntWritable, IntWritable, IntWritable>> inVertexIdMutations = serverData.getVertexMutations();
    int keySum = 0;
    for (Entry<IntWritable, VertexMutations<IntWritable, IntWritable, IntWritable, IntWritable>> entry : inVertexIdMutations.entrySet()) {
        synchronized (entry.getValue()) {
            keySum += entry.getKey().get();
            int vertexValueSum = 0;
            for (Vertex<IntWritable, IntWritable, IntWritable, IntWritable> vertex : entry.getValue().getAddedVertexList()) {
                vertexValueSum += vertex.getValue().get();
            }
            assertEquals(3, vertexValueSum);
            assertEquals(2, entry.getValue().getRemovedVertexCount());
            int removeEdgeValueSum = 0;
            for (Edge<IntWritable, IntWritable> edge : entry.getValue().getAddedEdgeList()) {
                removeEdgeValueSum += edge.getValue().get();
            }
            assertEquals(20, removeEdgeValueSum);
        }
    }
    assertEquals(55, keySum);
}

@Test
public void testDuplicateRpcPort() throws Exception {
    @SuppressWarnings("rawtypes")
    Context context = mock(Context.class);
    Configuration conf = new Configuration();
    conf.setInt("mapred.task.partition", 9);
    conf.setInt(GiraphJob.MAX_WORKERS, 13);
    when(context.getConfiguration()).thenReturn(conf);
    when(context.getJobID()).thenReturn(new JobID());
