        System.out.println("testBspCheckpoint: idSum = " + idSum + " fileLen = " + fileStatus.getLen());
    }
    // Restart the test from superstep 2
    System.out.println("testBspCheckpoint: Restarting from superstep 2" + " with checkpoint path = " + checkpointsDir);
    outputPath = getTempPath(getCallingMethodName() + "Restarted");
    GiraphJob restartedJob = prepareJob(getCallingMethodName() + "Restarted", SimpleCheckpointVertex.class, SimpleCheckpointVertex.SimpleCheckpointVertexWorkerContext.class, SimpleCheckpointVertex.SimpleCheckpointVertexMasterCompute.class, SimpleSuperstepVertexInputFormat.class, SimpleSuperstepVertexOutputFormat.class, outputPath);
    job.setMasterComputeClass(SimpleCheckpointVertex.SimpleCheckpointVertexMasterCompute.class);
    restartedJob.getConfiguration().set(GiraphJob.CHECKPOINT_DIRECTORY, checkpointsDir.toString());
    assertTrue(restartedJob.run(true));
    if (!runningInDistributedMode()) {
        long idSumRestarted = SimpleCheckpointVertex.SimpleCheckpointVertexWorkerContext.getFinalSum();
        System.out.println("testBspCheckpoint: idSumRestarted = " + idSumRestarted);
        assertEquals(idSum, idSumRestarted);
    }
}

