@Test
public void testGetChildrenExt() throws KeeperException, InterruptedException {
    if (zooKeeperExt == null) {
        System.out.println("testGetChildrenExt: No prop.zookeeper.list set, skipping test");
        return;
    }
    zooKeeperExt.create(BASE_PATH, null, Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
    zooKeeperExt.create(BASE_PATH + "/b", null, Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT_SEQUENTIAL);
    zooKeeperExt.create(BASE_PATH + "/a", null, Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT_SEQUENTIAL);
    zooKeeperExt.create(BASE_PATH + "/d", null, Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT_SEQUENTIAL);
    zooKeeperExt.create(BASE_PATH + "/c", null, Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT_SEQUENTIAL);
    List<String> fullPathList = zooKeeperExt.getChildrenExt(BASE_PATH, false, false, true);
    for (String fullPath : fullPathList) {
        assertTrue(fullPath.contains(BASE_PATH + "/"));
    }
    List<String> sequenceOrderedList = zooKeeperExt.getChildrenExt(BASE_PATH, false, true, true);
    for (String fullPath : sequenceOrderedList) {
        assertTrue(fullPath.contains(BASE_PATH + "/"));
    }
    assertEquals(4, sequenceOrderedList.size());
    assertTrue(sequenceOrderedList.get(0).contains("/b"));
    assertTrue(sequenceOrderedList.get(1).contains("/a"));
    assertTrue(sequenceOrderedList.get(2).contains("/d"));
    assertTrue(sequenceOrderedList.get(3).contains("/c"));
}

@Test
public void testEquality() {
    Iterable<String> one = Lists.newArrayList("one", "two", "three");
    Iterable<String> two = Lists.newArrayList("one", "two", "three");
    assertTrue(ComparisonUtils.equal(one, one));
    assertTrue(ComparisonUtils.equal(one, two));
    assertTrue(ComparisonUtils.equal(two, two));
    assertTrue(ComparisonUtils.equal(two, one));
}

@Test
public void testEqualityEmpty() {
    Iterable<String> one = Lists.newArrayList();
    Iterable<String> two = Lists.newArrayList();
    assertTrue(ComparisonUtils.equal(one, one));
    assertTrue(ComparisonUtils.equal(one, two));
    assertTrue(ComparisonUtils.equal(two, two));
    assertTrue(ComparisonUtils.equal(two, one));
}

@Test
public void testInEquality() {
    Iterable<String> one = Lists.newArrayList("one", "two", "three");
    Iterable<String> two = Lists.newArrayList("two", "three", "four");
    Iterable<String> three = Lists.newArrayList();
    assertFalse(ComparisonUtils.equal(one, two));
    assertFalse(ComparisonUtils.equal(one, three));
    assertFalse(ComparisonUtils.equal(two, one));
    assertFalse(ComparisonUtils.equal(two, three));
    assertFalse(ComparisonUtils.equal(three, one));
    assertFalse(ComparisonUtils.equal(three, two));
}

@Test
public void testInEqualityDifferentLengths() {
    Iterable<String> one = Lists.newArrayList("one", "two", "three");
    Iterable<String> two = Lists.newArrayList("one", "two", "three", "four");
    assertFalse(ComparisonUtils.equal(one, two));
    assertFalse(ComparisonUtils.equal(two, one));
}

@Test
public void testGetBasePath() {
    Configuration conf = new Configuration();
    // Default is empty, everything goes in root znode
    assertEquals("Default value for base path should be empty", "", ZooKeeperManager.getBasePath(conf));
    conf.set(GiraphJob.BASE_ZNODE_KEY, "/howdy");
    assertEquals("Base path should reflect value of " + GiraphJob.BASE_ZNODE_KEY, "/howdy", ZooKeeperManager.getBasePath(conf));
    conf.set(GiraphJob.BASE_ZNODE_KEY, "no_slash");
    try {
        ZooKeeperManager.getBasePath(conf);
        fail("Should not have allowed path without starting slash");
    } catch (IllegalArgumentException iae) {
        assertTrue(iae.getMessage().contains(GiraphJob.BASE_ZNODE_KEY));
    }
}
